// Manual isolated-fixture test. Never part of the app or automatic test suite.
// Explicit --isolated-outputs-ack-paced is required for physical writes.
// Only defined PC=>PLC addresses, one bit at a time; ACK-paced, no motion hold delay.
#include "../Evo/XgbXgtTcpReadWrite.h"
#include <array>
#include <chrono>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>
struct Case {std::string name;unsigned address,bit;bool ackOn=false,onObserved=false,ackOff=false,offObserved=false;unsigned before=0,onRead=0,offRead=0;};
class Test {
 using Clock=std::chrono::steady_clock;
 XgbXgtTcpReadWrite io_;DRegionWritePolicy policy_;std::ofstream trace_;Clock::time_point start_=Clock::now();bool captured_=false,armed_=false;std::array<bool,3> touched_{{false,false,false}};
 double Now()const{return std::chrono::duration<double,std::milli>(Clock::now()-start_).count();}
public:
 std::array<unsigned,3> original{};std::vector<Case> cases;unsigned writes=0;bool speedOn=false,speedOff=false,restored=false,heartbeatClear=false;unsigned heartbeatReads=0;double heartbeatDuration=0;
 Test(std::string ip,std::string path,bool armed):io_(ip,2004,1000),trace_(path),armed_(armed){if(!trace_)throw std::runtime_error("trace open");policy_.SetAuthorized(armed);policy_.AllowSpeedWord(armed);for(unsigned b:{0u,1u,2u,3u,15u})policy_.AllowBit(51,b);for(unsigned b=0;b<8;++b)policy_.AllowBit(52,b);if(!io_.Connect())throw std::runtime_error("connect");trace_<<"phase,elapsed_ms,address,word,hex,ack\n";}
 unsigned Read(unsigned a,std::string phase){std::vector<std::uint16_t>v;if(!io_.ReadWords(static_cast<std::uint16_t>(a),1,v)||v.size()!=1)throw std::runtime_error("read D"+std::to_string(a));trace_<<phase<<','<<Now()<<','<<a<<','<<v[0]<<",0x"<<std::hex<<v[0]<<std::dec<<",\n";trace_.flush();return v[0];}
 void Write(DRegionWritePolicy::PreparedWrite const& p,std::string phase){if(!armed_||p.decision!=DRegionWritePolicy::Decision::ReadyForExternalTransport||p.address<50||p.address>52)throw std::runtime_error("write denied");if((p.address==50&&p.value>1)||(p.address==51&&((p.value&0x7ff0)!=0||(p.value&6)==6))||(p.address==52&&(p.value>128||(p.value!=0&&(p.value&(p.value-1))!=0))))throw std::runtime_error("test range denied");touched_[p.address-50]=true;++writes;bool ack=io_.WritePrepared(p);trace_<<phase<<','<<Now()<<','<<p.address<<','<<p.value<<",0x"<<std::hex<<p.value<<std::dec<<','<<ack<<'\n';trace_.flush();if(!ack)throw std::runtime_error("write ACK unknown; no command retry");}
 void Capture(){unsigned d10=Read(10,"baseline");for(unsigned a=50;a<=52;++a)original[a-50]=Read(a,"baseline");captured_=true;std::cout<<"BASELINE D10="<<d10<<" D50="<<original[0]<<" D51="<<original[1]<<" D52="<<original[2]<<'\n';if(armed_&&((d10&1)||original[0]!=0||(original[1]&0x7fff)||original[2]!=0))throw std::runtime_error("not an idle isolated-test baseline; no test writes allowed");for(unsigned a=50;a<=52;++a)if(Read(a,"baseline_confirm")!=original[a-50])throw std::runtime_error("baseline changing; abort");}
 void Speed(){// Isolated protocol fixture range is explicitly 0..1; no Hz/scaling claim.
  Write(policy_.PrepareSpeed(1,true),"speed_on");speedOn=Read(50,"speed_readback")==1;Write(policy_.PrepareSpeed(0,true),"speed_restore");speedOff=Read(50,"speed_restored")==0;std::cout<<"D50 raw1 ON_read="<<speedOn<<" restore0="<<speedOff<<'\n';if(!speedOff)throw std::runtime_error("speed restore mismatch");}
 void Bit(unsigned a,unsigned b,std::string name){Case c;c.name=name;c.address=a;c.bit=b;auto mask=1u<<b;c.before=Read(a,"bit_before");unsigned controls=a==51?0x000f:0x00ff;if((c.before&controls&~mask)!=0)throw std::runtime_error("other control active");if(c.before&mask){Write(policy_.PrepareBit(static_cast<std::uint16_t>(a),b,false,static_cast<std::uint16_t>(c.before),true),"bit_preclear");if(Read(a,"bit_precleared")&mask)throw std::runtime_error("preclear failed");c.before=Read(a,"bit_before");}
  Write(policy_.PrepareBit(static_cast<std::uint16_t>(a),b,true,static_cast<std::uint16_t>(c.before),true),"bit_on");c.ackOn=true;c.onRead=Read(a,"bit_on_readback");c.onObserved=(c.onRead&mask)!=0;
  unsigned latest=Read(a,"bit_off_fresh");unsigned allowedAsync=a==51?0x8000:0;if(((c.before^latest)&~(mask|allowedAsync))!=0)throw std::runtime_error("non-target bits changed; abort remaining commands");
  Write(policy_.PrepareBit(static_cast<std::uint16_t>(a),b,false,static_cast<std::uint16_t>(latest),true),"bit_off");c.ackOff=true;c.offRead=Read(a,"bit_off_readback");c.offObserved=(c.offRead&mask)==0;cases.push_back(c);std::cout<<name<<" ON_ACK="<<c.ackOn<<" ON_read="<<c.onObserved<<" OFF_ACK="<<c.ackOff<<" OFF_read="<<c.offObserved<<" raw_on="<<c.onRead<<" raw_off="<<c.offRead<<'\n';if(!c.offObserved)throw std::runtime_error("OFF readback failed");}
 void Heartbeat(){unsigned before=Read(51,"heartbeat_before");if(before&0x7fff)throw std::runtime_error("control bits active before heartbeat");if(before&0x8000){Write(policy_.PrepareBit(51,15,false,static_cast<std::uint16_t>(before),true),"heartbeat_preclear");if(Read(51,"heartbeat_precleared")&0x8000)throw std::runtime_error("heartbeat preclear failed");}
  before=Read(51,"heartbeat_fresh");Write(policy_.PrepareBit(51,15,true,static_cast<std::uint16_t>(before),true),"heartbeat_on");auto start=Clock::now();while(std::chrono::duration<double,std::milli>(Clock::now()-start).count()<250&&heartbeatReads<256){auto v=Read(51,"heartbeat_observe");++heartbeatReads;if(v&0x7fff)throw std::runtime_error("other bits changed during heartbeat");if(!(v&0x8000)){heartbeatClear=true;break;}}
  heartbeatDuration=std::chrono::duration<double,std::milli>(Clock::now()-start).count();std::cout<<"HEARTBEAT auto_OFF="<<heartbeatClear<<" reads="<<heartbeatReads<<" duration_ms="<<heartbeatDuration<<'\n';auto current=Read(51,"heartbeat_off_fresh");Write(policy_.PrepareBit(51,15,false,static_cast<std::uint16_t>(current),true),"heartbeat_off");if(Read(51,"heartbeat_off_readback")&0x8000)throw std::runtime_error("heartbeat OFF failed");}
 bool Restore(){if(!captured_||writes==0){restored=true;return true;}try{if(!io_.Connect())throw std::runtime_error("cleanup connect");for(unsigned a=50;a<=52;++a){unsigned current=Read(a,"final_restore_read");if(!touched_[a-50])continue;unsigned wanted=original[a-50];if(a==51)wanted=(current&~0x800fu)|(original[1]&0x800f);if(a==52)wanted=(current&~0xffu)|(original[2]&0xff);if(current!=wanted){if(a==50)Write(policy_.PrepareSpeed(static_cast<std::uint16_t>(wanted),true),"final_restore_write");else{DRegionWritePolicy::PreparedWrite p;p.decision=DRegionWritePolicy::Decision::ReadyForExternalTransport;p.address=static_cast<std::uint16_t>(a);p.value=static_cast<std::uint16_t>(wanted);Write(p,"final_restore_write");}}}
  restored=true;for(unsigned a=50;a<=52;++a){auto value=Read(a,"final_state");std::cout<<"FINAL D"<<a<<'='<<value<<'\n';restored&=value==original[a-50];}std::cout<<"FINAL D10="<<Read(10,"final_feedback")<<'\n';return restored;}catch(std::exception const&e){std::cout<<"RESTORE_INCOMPLETE "<<e.what()<<'\n';return false;}}
 void Save(std::string path,std::string status){std::ofstream out(path);out<<"{\n  \"status\": \""<<status<<"\",\n  \"writes\": "<<writes<<",\n  \"baseline\": ["<<original[0]<<','<<original[1]<<','<<original[2]<<"],\n  \"restored\": "<<(restored?"true":"false")<<",\n  \"speed_on_read\": "<<(speedOn?"true":"false")<<",\n  \"speed_off_read\": "<<(speedOff?"true":"false")<<",\n  \"heartbeat_auto_off\": "<<(heartbeatClear?"true":"false")<<",\n  \"heartbeat_reads\": "<<heartbeatReads<<",\n  \"heartbeat_ms\": "<<heartbeatDuration<<",\n  \"cases\": [";for(std::size_t i=0;i<cases.size();++i){auto const&c=cases[i];if(i)out<<',';out<<"\n    {\"name\":\""<<c.name<<"\",\"address\":"<<c.address<<",\"bit\":"<<c.bit<<",\"on_read\":"<<(c.onObserved?"true":"false")<<",\"off_read\":"<<(c.offObserved?"true":"false")<<",\"raw_on\":"<<c.onRead<<",\"raw_off\":"<<c.offRead<<'}';}out<<"\n  ]\n}\n";}
};
int main(int argc,char**argv){if(argc!=4||std::string(argv[1])!="192.168.10.124")return 2;std::string mode=argv[2],stem=argv[3];if(mode!="--read-only"&&mode!="--isolated-outputs-ack-paced")return 2;bool armed=mode=="--isolated-outputs-ack-paced";
 try{Test test(argv[1],stem+".csv",armed);try{test.Capture();if(!armed){test.Save(stem+".json","READ_ONLY_BASELINE");return 0;}test.Speed();for(unsigned b:{1u,2u,3u})test.Bit(51,b,b==1?"D51_UP":b==2?"D51_DOWN":"D51_PUMP");for(unsigned b=0;b<8;++b)test.Bit(52,b,"D52_PORT"+std::to_string(b+1));test.Heartbeat();test.Bit(51,0,"D51_EMERGENCY");bool restored=test.Restore();bool observed=test.speedOn&&test.speedOff;for(auto const&c:test.cases)observed&=c.onObserved&&c.offObserved;test.Save(stem+".json",!restored?"RESTORE_INCOMPLETE":observed?"WRITE_READBACK_PASSED":"ACK_PASSED_ON_NOT_OBSERVED");std::cout<<"RESULT restored="<<restored<<" all_ON_OFF_observed="<<observed<<" writes="<<test.writes<<'\n';return restored&&observed?0:10;}
 catch(std::exception const&e){std::cout<<"ABORT "<<e.what()<<'\n';test.Restore();test.Save(stem+".json","ABORTED");return 11;}}
 catch(std::exception const&e){std::cout<<"SETUP_FAILED "<<e.what()<<'\n';return 12;}
}
